package com.bqsqwad.heartbreakhealer.feature.entertainment

/** Five additional complete, original ten-part stories. */
internal object StoryLibraryBatch3 {
    val stories = listOf(
        StorySeries("the_orchard_of_echoes", "The Orchard of Echoes", "A new caretaker finds that a neglected orchard holds the stories of an entire neighbourhood.", listOf(
            StoryPart(1, "The Rusted Gate", listOf("Mina's aunt asked her to help clear the old orchard before the land was sold. At the gate, Mina found a small bell and a board listing names instead of fruit varieties.", "The oldest neighbour, Mr Danjuma, said the orchard had once been a meeting place where people left messages for anyone who needed help. He remembered the bell, but not who had taken the message book.")),
            StoryPart(2, "A Book Beneath the Bench", listOf("Mina and her friend Seyi searched the benches and found a weatherproof box beneath one. Inside was a book filled with short notes: lost keys, job leads, recipes, and offers to help.", "Some notes were signed, others were anonymous. One page mentioned a missing community fund and a promise to account for every contribution.")),
            StoryPart(3, "The Unbalanced Page", listOf("The fund's page listed donations but no final total. Mina noticed that the ink changed halfway down, as if someone had copied the figures later.", "The local shopkeeper recognised the handwriting as belonging to the former treasurer, Mrs Eze. She was still in town and agreed to explain the old records.")),
            StoryPart(4, "The Treasurer's Ledger", listOf("Mrs Eze brought a ledger showing that the fund had paid for repairs to a nearby footbridge after heavy rain. The receipts were stored separately with the council.", "The bridge was still used every day, but no one remembered who had funded it. Mina realised the orchard notes were a record of quiet kindness, not a mystery about stolen money.")),
            StoryPart(5, "The Missing Receipt", listOf("At the council office, an archive clerk found a receipt filed under the bridge's old name. It matched the ledger exactly, including the date and amount.", "The clerk apologised for the confusing filing and offered to add a corrected note to the public record. Mrs Eze asked that the people who donated be acknowledged too.")),
            StoryPart(6, "Names on the Wall", listOf("Mina proposed a small display in the orchard listing the fund's contributors and the bridge project. Some donors had moved away, so the neighbours helped trace their families.", "A retired carpenter recognised his mother's name and brought a photograph of her helping plant the first trees. The orchard's history began to feel alive again.")),
            StoryPart(7, "A Difficult Decision", listOf("The land buyer offered to preserve a narrow strip of trees but planned to remove the benches and gathering space. The neighbours asked Mina to help prepare an alternative plan.", "They mapped the healthiest trees, measured the open area, and showed how a smaller development could leave room for a public garden. They also agreed to maintain it themselves.")),
            StoryPart(8, "The Community Proposal", listOf("The council hosted a meeting where residents presented the orchard's history, the bridge receipts, and a practical maintenance plan. The buyer listened and asked for a week to review the proposal.", "Mina worried that the memories would not be enough. Mrs Eze reminded her that a good plan needed both heart and evidence—and they had brought both.")),
            StoryPart(9, "A Place Kept Open", listOf("The buyer agreed to preserve the central orchard as a community garden, with a public path and clear maintenance responsibilities. The council recorded the agreement so it would not depend on a handshake.", "The neighbours repaired the benches and hung the old bell beside the entrance. Mina copied the message book and placed the original in the local archive.")),
            StoryPart(10, "The Bell at Sunset", listOf("At the garden's reopening, Mr Danjuma rang the bell and read a few messages from the old book. People recognised the help they had once received and offered new ways to support one another.", "Mina planted a young tree beside the gate and added a final page to the book: the orchard had not been saved by one person or one secret, but by a community willing to remember what it had built together. The land had a future, the records were clear, and the bell had a new purpose."))
        )),
        StorySeries("the_stationery_shop", "The Little Shop of Second Chances", "A quiet stationery shop becomes the starting point for a town-wide kindness project.", listOf(
            StoryPart(1, "The Blue Door", listOf("After school, Dara began helping at her uncle's stationery shop. The shop was nearly empty, and her uncle was considering closing it after the holiday season.", "One afternoon, a girl returned a notebook with a note tucked inside: 'Thank you for leaving the last page blank.' Dara wondered why a blank page mattered so much.")),
            StoryPart(2, "The Notebook Trail", listOf("Dara found that the notebook had been part of a box of donated supplies. A label on the box said 'Open Shelf Project' and listed a community centre that had closed years earlier.", "Her uncle explained that the project let students borrow stationery when they could not afford it. He had continued the idea quietly, but the records were incomplete.")),
            StoryPart(3, "The First Borrower", listOf("Dara tracked down the girl, whose name was Nneka. Nneka said the blank page had helped her write a letter to a teacher asking for extra help with a subject she found difficult.", "She wanted to repay the kindness by donating supplies, but Dara suggested they first learn how many students might need the service.")),
            StoryPart(4, "A Simple Survey", listOf("The school counsellor helped them prepare an anonymous survey about access to basic school supplies. The results showed that many students reused old notebooks and shared pens.", "Dara's uncle was surprised by the number. He agreed to reopen the Open Shelf Project if they could create a fair, private way to request supplies.")),
            StoryPart(5, "The Fair Shelf", listOf("They set up a shelf at the shop with notebooks, pencils, rulers, and art materials. Students could ask privately, with no explanation required.", "A local printer offered discounted notebooks, and a parent group volunteered to restock the shelf each month. Dara kept a simple inventory so donations could be accounted for.")),
            StoryPart(6, "A Rumour to Correct", listOf("Someone posted online that the shop was giving away supplies only to students with top grades. Dara knew it was false, but the rumour spread quickly.", "Her uncle asked the school to confirm the project's actual rules: anyone who needed supplies could request them, and academic results were never part of the decision.")),
            StoryPart(7, "The Open Afternoon", listOf("Dara organised an open afternoon where families could learn how the shelf worked. The counsellor explained privacy, while the printer showed how recycled paper could reduce costs.", "Nneka spoke about the blank page that had helped her ask for support. She did not share private details; she simply reminded everyone that asking for help was a useful skill.")),
            StoryPart(8, "A Shop Reimagined", listOf("The shop began hosting free homework sessions twice a week. Volunteers helped with reading, maths, and creative projects, while the shelves remained open for supplies.", "Dara's uncle found that people were visiting again—not only to buy things, but to contribute time and ideas. The shop was becoming useful in a way he had not expected.")),
            StoryPart(9, "The Ledger of Thanks", listOf("Dara made a public record of donations and supplies distributed, without listing the names of students who received them. The project could now show exactly where every contribution went.", "A small grant from the neighbourhood association covered the next six months. The shop's future was no longer uncertain, though the team knew it would need steady care.")),
            StoryPart(10, "Room for a New Page", listOf("At the end of term, the school displayed a thank-you card from students who had used the shelf. Dara's uncle decided to keep the shop open and dedicate one corner to the project.", "Dara placed a fresh notebook on the shelf, leaving its final page blank. Anyone could use it to write a question, an idea, or a message of encouragement. The little shop had found a second chance by offering one to others."))
        )),
        StorySeries("the_compass_in_the_attic", "The Compass in the Attic", "A family heirloom leads two cousins to a forgotten act of courage and a repaired relationship.", listOf(
            StoryPart(1, "A Needle That Wouldn't Settle", listOf("Cousins Imani and Folarin were sorting their grandmother's attic when they found a brass compass. Its needle spun until Imani placed it beside a handwritten route.", "The route ended at a railway footpath that had been closed for years. Their grandmother's initials were written beside the final turn.")),
            StoryPart(2, "The Old Photograph", listOf("A photograph showed their grandmother as a young woman standing beside a station worker and a group of children. On the back was a date and the words 'the day we found our way home'.", "Folarin thought it might be a family adventure story. Imani noticed that the children were carrying school bags and looked worried.")),
            StoryPart(3, "A Neighbour Remembers", listOf("An elderly neighbour recognised the station worker as Mr Lawal, who had helped guide children home during a sudden storm decades earlier.", "He remembered their grandmother organising the group and staying behind to make sure every child was accounted for. The family had never heard the story.")),
            StoryPart(4, "The Route Map", listOf("Mr Lawal's daughter found a map of the old footpath. It showed a safe route from the station to the school, avoiding a flooded underpass.", "The compass had belonged to the station worker, who gave it to their grandmother as thanks for her quick thinking. The needle spun because its casing had loosened over time.")),
            StoryPart(5, "A Family Disagreement", listOf("Imani wanted to restore the compass and donate it to the town museum. Folarin wanted to keep it as a family keepsake, and their discussion became tense.", "Their grandmother listened and said both ideas mattered. She suggested they learn more about the story before deciding what the compass should become.")),
            StoryPart(6, "The School Register", listOf("The school archive held a register from the storm year. It listed every child who had been safely reunited with family, along with a note praising the volunteers.", "The record confirmed the neighbour's memory. It also revealed that the school had never thanked the station staff who helped that day.")),
            StoryPart(7, "A Shared Choice", listOf("The cousins agreed to make a careful replica for the museum and keep the original in the family, with permission for it to be displayed on special occasions.", "A local craftsperson repaired the compass without replacing its worn brass casing. The needle settled again when the loose pivot was fixed.")),
            StoryPart(8, "The Reunion", listOf("The museum invited former pupils, station workers' families, and the cousins' grandmother to a small gathering. Several people brought their own memories of the storm.", "Mr Lawal's daughter presented the station staff's old logbook, which matched the school register. The two records together told the complete story.")),
            StoryPart(9, "A Route Remembered", listOf("The town added a plaque near the old footpath, explaining how volunteers and station staff had helped children reach safety. The path itself remained closed until it could be properly assessed.", "Imani and Folarin recorded their grandmother's account for the museum. They were glad they had not rushed to turn the compass into a trophy or a private secret.")),
            StoryPart(10, "True North", listOf("Their grandmother gave the original compass to the cousins together, asking them to care for it as a shared family responsibility. They placed it in a small display case at home.", "The needle pointed north, steady at last. Imani and Folarin understood that the compass had never been valuable because it could lead someone through a storm; it mattered because people had trusted one another when directions were hard to find. Their disagreement ended with a shared promise, and the family story finally had a place in the town's history."))
        )),
        StorySeries("the_sound_of_saturday", "The Sound of Saturday", "A neighbourhood music club discovers a way to bring generations together.", listOf(
            StoryPart(1, "The Quiet Hall", listOf("Every Saturday, the community hall stood empty except for a caretaker sweeping the floor. Timi asked whether the old piano could be used for a youth music club.", "The caretaker said the piano belonged to a group that had stopped meeting after its founder moved away. No one knew whether it still worked.")),
            StoryPart(2, "A Piano with a Past", listOf("A technician inspected the piano and found that it needed tuning and a few repairs. Timi's music teacher offered to help organise a fundraiser, but asked the students to prepare a realistic budget.", "Inside the piano bench, they found a programme from a concert held twenty years earlier. The list included a children's choir and a group of older drummers.")),
            StoryPart(3, "The Former Choir", listOf("Timi traced the choir director, Mrs Bello, who now taught music privately. She was delighted that the hall might sing again, but worried that nobody would remember the old songs.", "She offered to teach the students one song if they could find the original choir members and ask permission to use their arrangement.")),
            StoryPart(4, "The Drum Maker", listOf("The concert programme named a drum maker whose workshop was still open. He remembered lending instruments for the event and had kept a notebook of the rhythms used.", "He agreed to show the students how the rhythms worked, explaining that they should credit the makers and musicians who shaped the arrangement.")),
            StoryPart(5, "A Modern Setlist", listOf("The students proposed a concert mixing the old songs with new compositions. Some adults worried that the old music would be changed too much.", "Mrs Bello suggested a simple rule: preserve the original melody when performing the traditional song, and label any new arrangement clearly. Everyone agreed.")),
            StoryPart(6, "The Missing Permission", listOf("The original arrangement was credited to a local cultural group that had since reorganised. Timi contacted its current coordinator, who asked to review the programme and the planned recording.", "The coordinator approved a live performance but requested that no recording be sold or posted without a separate agreement. The students added the condition to their event plan.")),
            StoryPart(7, "Practice Together", listOf("Young musicians and former choir members began rehearsing every Saturday. At first, the different tempos clashed, but the group learned to listen and adjust.", "A quiet student named Boma suggested a hand signal to help the performers change sections together. It worked so well that Mrs Bello asked Boma to lead the final rehearsal.")),
            StoryPart(8, "The Rainy Rehearsal", listOf("Heavy rain kept many people away one Saturday, so the group practised in a smaller room. They used the time to check the seating plan and make sure the hall would be accessible.", "The caretaker found an old photograph of the first concert and hung it beside the new programme. The hall no longer felt abandoned.")),
            StoryPart(9, "Saturday Returns", listOf("The concert sold out its free seats, and the audience included families who had not visited the hall in years. The performers introduced each piece and credited its creators.", "Boma led the final transition with a clear signal. The music moved from the old arrangement into the students' new composition without losing the original melody.")),
            StoryPart(10, "An Ongoing Song", listOf("After the concert, the hall committee approved a monthly music club with a written schedule, equipment-care plan, and permission process for future performances.", "Mrs Bello donated copies of the original programme, while the drum maker offered a workshop. Timi looked at the once-empty hall and heard what had changed: not just music, but a community making room for each other's voices."))
        )),
        StorySeries("the_missing_mural", "The Missing Mural", "A faded wall painting leads a young artist to uncover the real story of a neighbourhood landmark.", listOf(
            StoryPart(1, "A Blank Wall", listOf("A new building covered the wall where a colourful mural had stood for years. Artist-in-training Lami was disappointed; the mural had been the first artwork she remembered seeing.", "A photograph in the library showed the mural in full colour, but its caption named only the school that commissioned it, not the artists.")),
            StoryPart(2, "The Caption Error", listOf("Lami asked the librarian about the mural. The librarian found a newspaper article describing a student art competition and naming three finalists.", "One finalist, Mr Akin, still taught art nearby. He remembered painting the mural with two friends and said the school had never received the final list of contributors.")),
            StoryPart(3, "Three Signatures", listOf("Mr Akin showed Lami a sketchbook with three signatures. The mural had been designed by a team, but only one name appeared in the newspaper because the reporter interviewed the person who was present that day.", "Lami decided to locate the other artists before proposing a replacement mural.")),
            StoryPart(4, "The Colour Merchant", listOf("The old paint shop owner remembered mixing the mural's colours. He had kept a receipt with the three artists' names and the colour codes.", "The receipt also showed that the mural had been funded by local businesses. Lami began to see the painting as a shared project rather than a single artist's achievement.")),
            StoryPart(5, "A Wall with Permission", listOf("The new building manager explained that the mural had been removed because the old wall was unsafe. The artwork had been photographed before demolition, but the new wall belonged to a different owner.", "Lami prepared a proposal for a smaller mural on the community centre wall and asked the manager to confirm the rights and permissions needed before using the old design.")),
            StoryPart(6, "The Other Artists", listOf("One artist had moved abroad; the other, Mrs Okeke, ran a design studio in another city. Both confirmed the shared authorship and gave permission for a new interpretation, provided all three were credited.", "They sent Lami the original sketches and explained why the mural had included a doorway, a river, and three birds: each represented a part of the neighbourhood's history.")),
            StoryPart(7, "A Community Design", listOf("Lami invited residents to contribute memories and symbols. The group chose to include a library book, a market basket, a bridge, and the three birds from the original mural.", "The artists reviewed the design online and suggested keeping the doorway motif as a link between the old and new paintings.")),
            StoryPart(8, "Painting Day", listOf("Volunteers prepared the community centre wall after the owner approved the materials and safety plan. The three original artists joined by video call while Lami and the local team painted.", "Children helped with a supervised section of simple patterns. Each volunteer's contribution was acknowledged, and the artists' names were placed clearly on the mural.")),
            StoryPart(9, "The Unveiling", listOf("At the unveiling, Mr Akin explained the mural's history and corrected the old newspaper credit. The librarian displayed the original photograph and the paint receipt as supporting records.", "The building manager attended and offered a small maintenance fund so the new mural could be protected. Residents suggested an annual day for local art.")),
            StoryPart(10, "A Wall That Speaks", listOf("Lami added a final detail: three birds flying through the painted doorway toward the river. The new mural did not copy the old one; it continued its story with the whole neighbourhood involved.", "The artists thanked Lami for asking questions before painting over history. The old wall was gone, but its creators were recognised, the new work had permission and proper credit, and the community had gained a landmark of its own."))
        ))
    )
}
